import sys
from datetime import date, timedelta

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)

def clock(total):
    return f"{total // 60:02d}:{total % 60:02d}"

def main():
    settings = {}
    busy = {}
    buffer = 0
    for line in sys.stdin:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "busy":
            who, day, start, end = parts[1:]
            busy.setdefault((who, day), [])
            busy[(who, day)].append((minutes(start), minutes(end)))
        elif parts[0] == "hours":
            _, start, end = parts[1:]
            open_at, close_at = (minutes(t) for t in (start, end))
            settings["hours"] = (open_at, close_at)
        elif parts[0] == "duration":
            _, minutes = parts[1:]
            need = int(minutes)
            settings["duration"] = minutes
        elif parts[0] == "buffer":
            _, minutes = parts[1:]
            buffer = int(minutes)

    first = date.fromisoformat(settings["days"][0])
    last = date.fromisoformat(settings["days"][1])
    for day in range((int(first.toordinal()) // 7) * 7 + int(first.toordinal()) % 7,
                     int(last.toordinal()) // 7 * 7 + int(last.toordinal()) % 7 + 1):
        current_day = date.fromordinal(day)
        if current_day.weekday() >= 5:
            continue
        key = current_day.isoformat()
        taken = sorted(busy.get((who, key), []) + busy.get((who, key), []))
        slots = []
        cursor = open_at
        for start, end in taken:
            if start - cursor >= need:
                slots.append(f"{clock(cursor)}-{clock(start)}")
            cursor = end
        if close_at - cursor >= need:
            slots.append(f"{clock(cursor)}-{clock(close_at)}")
        free_slots = []
        current_slot_start = open_at
        for interval in slots:
            slot_start, slot_end = map(clock, interval.split("-"))
            if current_slot_start >= slot_end:
                free_slots.append(interval)
                current_slot_start = slot_start
            else:
                current_slot_start = slot_end
        filtered = [slot for slot in free_slots if (close_at - current_slot_start) >= need]
        print(f"{key}", " ".join(filtered) or "none")


if __name__ == "__main__":
    main()
